// Kepler quantitative verification — all numbers derived from first principles.
const R = 6371.0088; // mean Earth radius, km (IUGG mean radius)

function toRad(d){ return d*Math.PI/180; }

// Great-circle distance (haversine)
function gcDist(lat1,lon1,lat2,lon2){
  const p1=toRad(lat1), p2=toRad(lat2), dp=toRad(lat2-lat1), dl=toRad(lon2-lon1);
  const a = Math.sin(dp/2)**2 + Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;
  return 2*R*Math.asin(Math.sqrt(a));
}

// Azimuthal equidistant (flat-Earth-standard) map distance from North Pole center
function flatDist(lat,lon){ // distance on polar azimuthal equidistant map
  const colat = Math.PI/2 - toRad(lat); // degrees above horizon
  return toRad(90-lat)*R; // rho = colatitude * R, regardless of lon
}

const cities = {
  Johannesburg: [-26.20, 28.03], Perth: [-31.95, 115.86],
  Sydney: [-33.87, 151.21], Santiago: [-33.45, -70.67],
  "Cape Town": [-33.92, 18.42], Stanley: [-51.70, -57.85],
  Auckland: [-37.01, 174.79], Honolulu: [21.31, -157.86],
};

const pairs = [["Johannesburg","Perth"],["Sydney","Santiago"],["Cape Town","Stanley"],["Sydney","Johannesburg"],["Auckland","Honolulu"]];
console.log("pair | great-circle km | azimuthal(N-pole) km | ratio (flat/spherical)");
for(const [a,b] of pairs){
  const A=cities[a], B=cities[b];
  const gc = gcDist(A[0],A[1],B[0],B[1]);
  const f1 = flatDist(A[0],A[1]), f2 = flatDist(B[0],B[1]);
  // on azimuthal equidistant map the path between two points is not the straight chord;
  // the flat-Earth-claimed distance is measured along great-circle-in-projection which on
  // azimuthal equidistant equals the true great-circle bearing-polar geometry; the standard
  // flat-Earth map distance is the polar-equidistant straight line through the map:
  // distance = sqrt(f1^2 + f2^2 - 2 f1 f2 cos(dlon)) as measured on the flat map
  const dlon = Math.abs(toRad(A[1]-B[1]));
  const flatMap = Math.sqrt(f1*f1 + f2*f2 - 2*f1*f2*Math.cos(dlon));
  console.log(`${a}-${b}: GC=${gc.toFixed(0)} km | flat-map=${flatMap.toFixed(0)} km | ratio=${(flatMap/gc).toFixed(2)}`);
}

// Eratosthenes: 5000 stadia per 1/50 circle -> 250,000 stadia; error for stadia definitions
const circum_km = 40075; // equatorial
const stadia = {Egyptian:157.5, Olympic:176.4, Attic:185.0,... "Roman":185.0, "Phoenician/Egyptian alt":209.0};
console.log("\nEratosthenes 250,000 stadia:");
for(const [name,m] of Object.entries(stadia)){
  const km = 250000*m/1000;
  console.log(`  ${name} stadion (${m} m): ${km.toFixed(0)} km -> error ${((km-circum_km)/circum_km*100).toFixed(1)}%`);
}

// Foucault: T = 24 sidereal h / sin(lat); sidereal day = 23.9345 h
const sid = 23.93447;
for(const [name,lat] of Object.entries({Paris:48.85,"North Pole":90,"Sydney":-33.87,"Quito":-0.18})){
  console.log(`Foucault precession period at ${name} (lat ${lat}): ${(sid/Math.abs(Math.sin(toRad(lat)))).toFixed(2)} h; rate ${(15*Math.abs(Math.sin(toRad(lat)))).toFixed(2)} deg/h`);
}

// Horizon distance, no refraction: d = sqrt(2Rh)
function horizon(h){ return Math.sqrt(2*R*h); }
function horizonRefract(h){ return horizon(h)*1.072; }
console.log("\nHull-down visibility (geometric / with refraction):");
for(const [eh,hh] of [[3,30],[3,50],[10,50],[2,20]]){
  console.log(`  eye ${eh} m, ship ${hh} m: geometric sum = ${(horizon(eh)+horizon(hh)).toFixed(1)} km; with refraction ~${(horizonRefract(eh)+horizonRefract(hh)).toFixed(1)} km`);
}

// g variation (IGF-1980): g = 9.7803184(1+0.0053024 sin^2 p - 0.0000059 sin^2 2p)
function g(lat){ const p=toRad(lat); return 9.7803184*(1+0.0053024*Math.sin(p)**2-0.0000059*Math.sin(2*p)**2); }
console.log("\nSurface gravity: equator", g(0).toFixed(4), "m/s^2; 45deg", g(45).toFixed(4), "; pole", g(90).toFixed(4), "; variation", ((g(90)-g(0))/g(0)*100).toFixed(2)+"%");
console.log("Sun elevation at local midnight on Dec 21: South Pole 90 = sun up (summer).");

